ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"apiName": Mule::p("api.name"),
	"apiVersion": Mule::p("api.version"),
	"correlationId" : correlationId,
	"error" : {
	    "description" : error.description,
	    "code": "400",
	    "timestamp": now(),
	    "additionalDetails": (
	    	if(isEmpty(error.errorMessage.payload)) 
	    		(error.exception.cause.exceptionMessage default "Could not retrieve exact error")
	    	else
	    		(error.errorMessage.payload default "")
	    )
	}
}

